/** The docs this site serves to agents, generated by vite-plugin-docs on every build. */
import {
	manifest,
	llmsIndex,
	llmsFull,
	documents,
	sections,
	type Doc,
	type Manifest,
	type Section
} from 'virtual:docs';

export { manifest, llmsIndex, llmsFull, documents, sections };
export type { Doc, Manifest, Section };

/** Same value the API sends: both hosts read the same manifest. */
const etag = `"docs-${manifest.version}"`;

/** A disagreement here means a half-finished generation, so fail loudly. */
function verify(): void {
	if (manifest.docs.length !== manifest.doc_count) {
		throw new Error(`agentdocs: manifest lists ${manifest.docs.length} docs but claims ${manifest.doc_count}`);
	}
	if (Object.keys(documents).length !== manifest.docs.length) {
		throw new Error('agentdocs: documents and manifest disagree on how many docs exist');
	}
	for (const doc of manifest.docs) {
		const body = documents[doc.slug];
		if (body === undefined) {
			throw new Error(`agentdocs: ${doc.slug} is in the manifest but missing from documents`);
		}
		if (new TextEncoder().encode(body).length !== doc.bytes) {
			throw new Error(`agentdocs: ${doc.slug} does not match the size in the manifest`);
		}
		if (!llmsIndex.includes(doc.url)) {
			throw new Error(`agentdocs: the index does not link ${doc.url}`);
		}
	}
}

verify();

/** llmstxt.org v2 link relations. */
export const links = {
	index: '</llms-full.txt>; rel="alternate"; type="text/markdown"',
	describedBy: '</llms.txt>; rel="describedby"'
} as const;

/** If-None-Match is a list and may be weak, so compare entity-tags, not strings. */
function notModified(header: string | null, tag: string): boolean {
	return (header ?? '').split(',').some((candidate) => {
		const value = candidate.trim();
		return value === tag || value === '*' || value.replace(/^W\//, '') === tag;
	});
}

/** One response, with the headers that let a caller revalidate instead of re-read. */
export function respond(request: Request, body: string, contentType: string, link: string): Response {
	const headers = new Headers({
		'content-type': contentType,
		'x-docs-version': manifest.version,
		'x-api-version': manifest.api_version,
		'x-docs-count': String(manifest.doc_count),
		etag,
		// Revalidate rather than trust: these change with the code.
		'cache-control': 'public, max-age=0, must-revalidate',
		link
	});

	if (notModified(request.headers.get('if-none-match'), etag)) {
		return new Response(null, { status: 304, headers });
	}
	return new Response(body, { status: 200, headers });
}
